   922  ssize_t expect_default(h2o_http2_conn_t *conn, const uint8_t *src, size_t len, const char **err_desc)
   923  {
   924      h2o_http2_frame_t frame;
   925      ssize_t ret;
   926      static int (*FRAME_HANDLERS[])(h2o_http2_conn_t * conn, h2o_http2_frame_t * frame, const char **err_desc) = {
   927          handle_data_frame,                /* DATA */
   928          handle_headers_frame,             /* HEADERS */
   929          handle_priority_frame,            /* PRIORITY */
   930          handle_rst_stream_frame,          /* RST_STREAM */
   931          handle_settings_frame,            /* SETTINGS */
   932          handle_push_promise_frame,        /* PUSH_PROMISE */
   933          handle_ping_frame,                /* PING */
   934          handle_goaway_frame,              /* GOAWAY */
   935          handle_window_update_frame,       /* WINDOW_UPDATE */
   936          handle_invalid_continuation_frame /* CONTINUATION */
   937      };
   938
   939      if ((ret = h2o_http2_decode_frame(&frame, src, len, &H2O_HTTP2_SETTINGS_HOST, err_desc)) < 0)
   940          return ret;
   941
   942      if (frame.type < sizeof(FRAME_HANDLERS) / sizeof(FRAME_HANDLERS[0])) {
   943          int hret = FRAME_HANDLERS[frame.type](conn, &frame, err_desc);
   944          if (hret != 0)
   945              ret = hret;
   946      } else {
   947          fprintf(stderr, "skipping frame (type:%d)\n", frame.type);
   948      }
   949
   950      return ret;
   951  }
