   995  static void on_read(h2o_socket_t *sock, const char *err)
   996  {
   997      h2o_http2_conn_t *conn = sock->data;
   998
   999      if (err != NULL) {
  1000          conn->super.ctx->http2.events.read_closed++;
  1001          h2o_socket_read_stop(conn->sock);
  1002          close_connection(conn);
  1003          return;
  1004      }
  1005
  1006      update_idle_timeout(conn);
  1007      if (parse_input(conn) != 0)
  1008          return;
  1009
  1010      /* write immediately, if there is no write in flight and if pending write exists */
  1011      if (h2o_timeout_is_linked(&conn->_write.timeout_entry)) {
  1012          h2o_timeout_unlink(&conn->_write.timeout_entry);
  1013          do_emit_writereq(conn);
  1014      }
  1015  }
